  nativeInput?: boolean;
  /** 默认仅在 type="search" 时启用；清空不提交表单。 */
  clearable?: boolean;
  clearLabel?: string;
  onClear?: () => void;
  /** 默认仅在 type="password" 时启用。 */
  visibilityToggle?: boolean;
  visible?: boolean;
  defaultVisible?: boolean;
  onVisibleChange?: (visible: boolean) => void;
  /** 稳定的开关名称；aria-pressed 表达密码当前是否可见。 */
  showLabel?: string;
}

